<template>
 <view class="training-page"><NativeStatusSpacer/><view class="top"><button @tap="back">‹</button><text>课程与活动申请</text><view/></view>
 <view class="paper"><view class="intro"><text class="intro-icon">✦</text><view><text class="title">仅可申请已关联机构</text><text>开设的课程或活动</text></view></view>
  <view v-if="loading" class="state">正在加载</view><view v-else-if="error" class="state error">{{error}}</view>
  <template v-if="enabled"><view class="form-row"><text class="label">成长小主人</text><picker :range="students.map(s=>s.studentName)" @change="chooseChild"><view class="field">{{students.find(s=>s.studentId===studentId)?.studentName||'请选择'}} ⌄</view></picker></view>
  <view class="form-row"><text class="label">学校或培训机构</text><picker :range="institutions.map(i=>i.name)" @change="chooseInstitution"><view class="field">{{institutions.find(i=>i.id===institutionId)?.name||'请选择已关联机构'}} ⌄</view></picker></view>
  <view class="form-row type-row"><text class="label">申请类型</text><view class="type-options"><view class="type-option" role="radio" :aria-checked="requestType==='OFFICIAL_COURSE'" @tap="chooseRequestType('OFFICIAL_COURSE')"><text class="radio" :class="{checked:requestType==='OFFICIAL_COURSE'}"/>正式课程</view><view class="type-option" role="radio" :aria-checked="requestType==='CLUB_ACTIVITY'" @tap="chooseRequestType('CLUB_ACTIVITY')"><text class="radio" :class="{checked:requestType==='CLUB_ACTIVITY'}"/>社团活动</view></view></view><text class="label">选择培训项目</text><view v-if="!filteredPrograms.length" class="state">{{institutionId?(programHasMore?'暂无此类型项目，可继续加载项目':'暂无此类型项目'):'请先选择机构'}}</view><view v-for="item in filteredPrograms" :key="item.programOrganizationId" class="program" :class="{selected:programId===item.programOrganizationId}" @tap="selectProgram(item)"><view><text>{{item.programName}}</text><text class="secondary">{{item.programType==='OFFICIAL_COURSE'?'正式课程':'社团活动'}}</text></view><text>{{programId===item.programOrganizationId?'✓':'○'}}</text></view><button v-if="programHasMore" class="more" :disabled="programLoading" @tap="morePrograms">加载更多项目</button>
  <text class="label">申请理由</text><textarea v-model="reason" maxlength="200" placeholder="填写兴趣或学习需求（选填）"/><button class="primary" :disabled="saving||!programId||programLoading" @tap="submit">{{saving?'提交中':'提交申请'}}</button>
  <view class="section-title">我的申请</view><view v-for="item in requests" :key="item.id" class="request"><view><text>{{item.studentName}} · {{item.programName}}</text><text class="secondary">{{item.institutionName}} · {{trainingStatusLabel[item.status]}}</text><text v-if="item.reviewReason" class="secondary">{{item.reviewReason}}</text></view><button v-if="item.status==='PENDING'" :disabled="saving" @tap="withdraw(item)">撤回</button></view><view v-if="requestLoading" class="state">正在加载申请</view><view v-else-if="requestError" class="state error"><text>{{requestError}}</text><button @tap="moreRequests">重试申请列表</button></view><view v-else-if="!requests.length" class="state">暂无申请</view><button v-if="requestHasMore" class="more" :disabled="requestLoading" @tap="moreRequests">加载更多申请</button>
  </template><text v-if="actionError" class="state error">{{actionError}}</text>
 </view></view>
</template>
<script setup lang="ts">
import {ref,computed} from 'vue';
import {onShow,onHide,onUnload,onReachBottom} from '@dcloudio/uni-app';
import NativeStatusSpacer from '@/components/NativeStatusSpacer.vue';
import {trainingApi,trainingStatusLabel,type TrainingProgram,type TrainingRequest} from '@/api/training';
import {listParentRelationshipStudents,type ParentRelationshipStudent} from '@/api/parent-relationship';
import {getParentSession} from '@/session/parent-session';
import {request} from '@/api/http';
import {getMiniappCapabilities} from '@/api/capability';
const students=ref<ParentRelationshipStudent[]>([]),institutions=ref<{id:string;name:string;typeCode:string}[]>([]),programs=ref<TrainingProgram[]>([]),requests=ref<TrainingRequest[]>([]);
const requestError=ref('');
const requestType=ref<'OFFICIAL_COURSE'|'CLUB_ACTIVITY'>('OFFICIAL_COURSE');
const filteredPrograms=computed(()=>programs.value.filter(p=>p.programType===requestType.value));
const studentId=ref(''),institutionId=ref(''),programId=ref(''),reason=ref(''),error=ref(''),actionError=ref(''),loading=ref(false),saving=ref(false),enabled=ref(false),programLoading=ref(false),requestLoading=ref(false),programHasMore=ref(false),requestHasMore=ref(false);
let token='',familyId='',visible=false,epoch=0,choice=0,programPage=0,requestPage=0,requestRevision=0;
function selection(){return uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string;typeCode?:string}|undefined;}
function current(n:number){const s=selection();return visible&&n===epoch&&getParentSession()?.accessToken===token&&s?.accessToken===token&&s.organizationId===familyId&&s.typeCode==='FAMILY';}
function clearChoice(){requestType.value='OFFICIAL_COURSE';++choice;institutionId.value='';programId.value='';institutions.value=[];programs.value=[];programPage=0;programHasMore.value=false;programLoading.value=false;}
async function initialize(){visible=true;const n=++epoch;token=getParentSession()?.accessToken||'';familyId=selection()?.organizationId||'';enabled.value=false;students.value=[];studentId.value='';clearChoice();++requestRevision;requestLoading.value=false;requestError.value='';requests.value=[];requestPage=0;requestHasMore.value=false;error.value='';actionError.value='';loading.value=true;if(!token||!current(n)){error.value='请先进入所属家庭';loading.value=false;return;}try{const [me,cap]=await Promise.all([request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}}),getMiniappCapabilities()]);if(!current(n))return;if(!me.permissionCodes.includes('STUDENT_TRAINING_REQUEST_CREATE')||!cap.studentOrganizationRelationshipEnabled)throw Error('当前账号暂无申请权限或功能未启用');const children=await listParentRelationshipStudents(token);if(!current(n))return;students.value=children;enabled.value=true;await moreRequests();}catch(e){if(current(n))error.value=e instanceof Error?e.message:'加载失败';}finally{if(current(n))loading.value=false;}}
async function chooseChild(e:{detail:{value:string}}){if(!enabled.value||saving.value||!current(epoch))return;studentId.value=students.value[Number(e.detail.value)]?.studentId||'';clearChoice();actionError.value='';if(!studentId.value)return;const n=epoch,c=choice;try{const result=await trainingApi.institutions(token,studentId.value,familyId);if(current(n)&&c===choice)institutions.value=result;}catch(e){if(current(n)&&c===choice)actionError.value=e instanceof Error?e.message:'机构加载失败';}}
async function chooseInstitution(e:{detail:{value:string}}){if(!enabled.value||saving.value||!current(epoch))return;++choice;programLoading.value=false;institutionId.value=institutions.value[Number(e.detail.value)]?.id||'';programId.value='';programs.value=[];programPage=0;programHasMore.value=!!institutionId.value;await morePrograms();}
async function morePrograms(){if(!enabled.value||!current(epoch)||!programHasMore.value||programLoading.value)return;const n=epoch,c=choice;programLoading.value=true;actionError.value='';try{const result=await trainingApi.programs(token,{studentId:studentId.value,familyOrganizationId:familyId,institutionOrganizationId:institutionId.value},programPage+1);if(!current(n)||c!==choice)return;const seen=new Set(programs.value.map(p=>p.programOrganizationId));programs.value.push(...result.items.filter(p=>!seen.has(p.programOrganizationId)&&!!seen.add(p.programOrganizationId)));programPage=result.page;programHasMore.value=result.items.length>0&&result.page*result.pageSize<result.total;}catch(e){if(current(n)&&c===choice)actionError.value=e instanceof Error?e.message:'项目加载失败';}finally{if(current(n)&&c===choice)programLoading.value=false;}}
function chooseRequestType(value:string){if(!enabled.value||saving.value||!current(epoch)||value!=='OFFICIAL_COURSE'&&value!=='CLUB_ACTIVITY'||value===requestType.value)return;requestType.value=value;programId.value='';actionError.value='';}
function selectProgram(item:TrainingProgram){if(!saving.value&&current(epoch)&&programs.value.some(p=>p.programOrganizationId===item.programOrganizationId)&&item.programType===requestType.value&&item.enrollable==='ENABLED')programId.value=item.programOrganizationId;}
async function moreRequests(){if(!enabled.value||!current(epoch)||requestLoading.value||requestPage>0&&!requestHasMore.value)return;const n=epoch,r=requestRevision;requestLoading.value=true;requestError.value='';try{const result=await trainingApi.requests(token,{familyOrganizationId:familyId},requestPage+1);if(!current(n)||r!==requestRevision)return;const seen=new Set(requests.value.map(r=>r.id));requests.value.push(...result.items.filter(r=>!seen.has(r.id)&&!!seen.add(r.id)));requestPage=result.page;requestHasMore.value=result.items.length>0&&result.page*result.pageSize<result.total;}catch(e){if(current(n)&&r===requestRevision)requestError.value=e instanceof Error?e.message:'申请加载失败';}finally{if(current(n)&&r===requestRevision)requestLoading.value=false;}}
async function submit(){if(!enabled.value||!current(epoch)||saving.value||programLoading.value)return;const program=programs.value.find(p=>p.programOrganizationId===programId.value);if(!studentId.value||!institutionId.value||!program||program.programType!==requestType.value||program.enrollable!=='ENABLED'){actionError.value='请选择成长小主人、机构及项目';return;}const n=epoch;saving.value=true;actionError.value='';try{await trainingApi.apply(token,{studentId:studentId.value,familyOrganizationId:familyId,institutionOrganizationId:institutionId.value,programOrganizationId:programId.value,requestType:program.programType,reason:reason.value.trim()});if(!current(n))return;programId.value='';reason.value='';++requestRevision;requestLoading.value=false;requestError.value='';requests.value=[];requestPage=0;requestHasMore.value=false;await moreRequests();if(current(n))uni.showToast({title:'申请已提交',icon:'success'});}catch(e){if(current(n))actionError.value=e instanceof Error?e.message:'提交失败';}finally{if(current(n))saving.value=false;}}
function withdraw(item:TrainingRequest){if(!enabled.value||!current(epoch)||saving.value||item.status!=='PENDING')return;const n=epoch;uni.showModal({title:'撤回申请',content:`确认撤回“${item.programName}”的申请？`,success:async result=>{if(!result.confirm||!current(n)||saving.value)return;saving.value=true;try{const updated=await trainingApi.withdraw(token,item.id);if(current(n))requests.value=requests.value.map(r=>r.id===item.id?updated:r);}catch(e){if(current(n))actionError.value=e instanceof Error?e.message:'撤回失败';}finally{if(current(n))saving.value=false;}}});}
function hide(){visible=false;++epoch;++choice;++requestRevision;requestError.value='';enabled.value=false;saving.value=false;loading.value=false;programLoading.value=false;requestLoading.value=false;students.value=[];programs.value=[];requests.value=[];}
function back(){uni.navigateBack();}
onShow(initialize);onHide(hide);onUnload(hide);onReachBottom(()=>{if(!requestError.value)void moreRequests();});
</script>
<style scoped>
.training-page{min-height:100vh;background:#17634d;color:#23342f}.top{height:86rpx;display:flex;align-items:center;justify-content:space-between;padding:0 26rpx;color:white;font-size:32rpx;font-weight:600}.top button{margin:0;width:50rpx;background:transparent;color:white;font-size:46rpx;padding:0}.top>view{width:50rpx}.paper{min-height:calc(100vh - 180rpx);background:linear-gradient(115deg,#fff,#f6faf7);border-radius:32rpx 32rpx 0 0;padding:24rpx 30rpx 44rpx;box-sizing:border-box}.intro{padding:20rpx 24rpx;margin-bottom:18rpx;display:flex;align-items:center;gap:22rpx;background:#eaf8ee;border:1rpx solid #d8efde;border-radius:16rpx;color:#34574b;font-size:25rpx;line-height:1.65}.intro>view{display:flex;flex-direction:column}.intro-icon{font-size:48rpx;color:#15945d}.title{font-size:25rpx;font-weight:500}.form-row{display:flex;align-items:center;gap:20rpx;min-height:106rpx}.form-row .label{width:205rpx;flex-shrink:0;margin:0}.form-row picker{flex:1;min-width:0}.type-row{align-items:flex-start;padding:12rpx 0}.type-options{display:flex;flex-direction:column;gap:22rpx;padding-top:5rpx}.type-option{display:flex;align-items:center;gap:16rpx;font-size:26rpx;line-height:1.5}.radio{width:34rpx;height:34rpx;box-sizing:border-box;display:inline-block;border:2rpx solid #b4bdb8;border-radius:50%;background:white}.radio.checked{border-color:#17805d;background:#17805d;box-shadow:inset 0 0 0 5rpx white}.label{display:block;margin:22rpx 0 14rpx;font-size:27rpx;font-weight:500}.field{background:#f4f5f6;border:1rpx solid #e9ebed;border-radius:14rpx;padding:17rpx 20rpx;font-size:26rpx;line-height:1.5}.program{background:#f5f6f7;border:1rpx solid #e4e9e6;border-radius:14rpx;padding:18rpx 20rpx;margin-bottom:12rpx;display:flex;justify-content:space-between;align-items:center;font-size:26rpx}.selected{border-color:#1d7759;background:#edf5ee}.secondary{display:block;margin-top:7rpx;color:#85948a;font-size:23rpx;line-height:1.5}textarea{width:100%;height:235rpx;box-sizing:border-box;background:#f8faf9;border:1rpx solid #dfe5e1;border-radius:16rpx;padding:22rpx;font-size:26rpx;line-height:1.6}.primary{background:#176b4f;color:white;border-radius:16rpx;margin:40rpx 0;font-size:29rpx;font-weight:600}.primary[disabled]{background:#e2eae5;color:#7b9285}.section-title{font-size:29rpx;font-weight:650;margin:32rpx 0 12rpx;padding-top:22rpx;border-top:1rpx solid #e1e9e2}.request{display:flex;gap:16rpx;align-items:center;padding:20rpx 0;border-bottom:1rpx solid #e1e9e2;font-size:26rpx}.request>view{flex:1}.request button,.more{font-size:24rpx;background:#edf3ed;color:#236b50;margin:14rpx 0}.state{display:block;padding:20rpx 0;font-size:24rpx;color:#8a988e}.error{color:#b45d47}button::after{border:0}
</style>


